import json
from itertools import permutations

def solve():
    houses = [1, 2, 3, 4, 5]

    Names = ["Alice", "Peter", "Bob", "Eric", "Arnold"]
    Heights = ["very short", "short", "tall", "average", "very tall"]
    Mothers = ["Janelle", "Kailyn", "Penny", "Holly", "Aniya"]
    Hairs = ["blonde", "black", "gray", "red", "brown"]

    # Helper to get position of a value in an arrangement (list indexed by house-1)
    def pos_of(arr, value):
        return arr.index(value)

    solution = None

    # Iterate over possible placements of mothers with constraint 14: Kailyn in the third house
    for mothers_perm in permutations(Mothers):
        if mothers_perm[2] != "Kailyn":
            continue

        pos_m = {mothers_perm[i]: i for i in range(5)}

        # Heights permutations subject to constraints: 1,2,6,10,13
        for heights_perm in permutations(Heights):
            pos_hgt = {heights_perm[i]: i for i in range(5)}

            # 10. Kailyn directly left of short
            if pos_m["Kailyn"] + 1 != pos_hgt["short"]:
                continue

            # 2. Two houses between average and short
            if abs(pos_hgt["average"] - pos_hgt["short"]) != 3:
                continue

            # 1. Tall is mother Holly
            if pos_hgt["tall"] != pos_m["Holly"]:
                continue

            # 6. Very short is mother Penny
            if pos_hgt["very short"] != pos_m["Penny"]:
                continue

            # 13. Aniya and very short are next to each other
            if abs(pos_m["Aniya"] - pos_hgt["very short"]) != 1:
                continue

            # Hairs permutations subject to constraints: 3,4,7,12
            for hairs_perm in permutations(Hairs):
                pos_hair = {hairs_perm[i]: i for i in range(5)}

                # 3. Gray hair directly left of Janelle (mother)
                if not (pos_hair["gray"] + 1 == pos_m["Janelle"]):
                    continue

                # 4. Black hair not in the fourth house
                if pos_hair["black"] == 3:
                    continue

                # 7. Eric (black hair) and gray hair are next to each other
                if abs(pos_hair["black"] - pos_hair["gray"]) != 1:
                    continue

                # 12. Brown hair somewhere to the left of Janelle (mother)
                if not (pos_hair["brown"] < pos_m["Janelle"]):
                    continue

                # Names permutations subject to constraints: 5,8,9,11
                for names_perm in permutations(Names):
                    pos_name = {names_perm[i]: i for i in range(5)}

                    # 8. Bob in the fifth house
                    if pos_name["Bob"] != 4:
                        continue

                    # 5. Eric has black hair
                    if pos_name["Eric"] != pos_hair["black"]:
                        continue

                    # 9. Red hair is Peter
                    if pos_name["Peter"] != pos_hair["red"]:
                        continue

                    # 11. Arnold is brown hair
                    if pos_name["Arnold"] != pos_hair["brown"]:
                        continue

                    # All constraints satisfied
                    solution = {
                        "House": [str(i+1) for i in range(5)],
                        "Name": list(names_perm),
                        "Height": list(heights_perm),
                        "Mother": list(mothers_perm),
                        "Hair": list(hairs_perm),
                    }
                    # Since the puzzle should have a unique solution, break all loops
                    break
                if solution:
                    break
            if solution:
                break
        if solution:
            break

    if not solution:
        raise RuntimeError("No solution found")

    header = ["House", "Name", "Height", "Mother", "Hair"]
    rows = []
    for i in range(5):
        rows.append([
            solution["House"][i],
            solution["Name"][i],
            solution["Height"][i],
            solution["Mother"][i],
            solution["Hair"][i],
        ])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    solve()
